def dedupe_contacts(rows):
    import re
    from datetime import datetime

    def normalize_email(value):
        match = re.search(r"<([^<>]*)>", value)
        email = (match.group(1) if match else value).strip().lower()

        if email.count("@") != 1:
            return ""

        local, domain = email.split("@")
        if domain in {"gmail.com", "googlemail.com"}:
            local = local.split("+", 1)[0].replace(".", "")
            domain = "gmail.com"

        if not local or "." not in domain or domain.startswith(".") or domain.endswith("."):
            return ""
        return f"{local}@{domain}"

    def normalize_phone(value):
        value = re.split(r"ext|x|#", value, maxsplit=1, flags=re.IGNORECASE)[0]
        phone = re.sub(r"\D", "", value)
        if len(phone) == 11 and phone.startswith("1"):
            phone = phone[1:]
        return phone if len(phone) == 10 and phone[0] not in "01" else ""

    def normalize_zip(value):
        value = value.strip()
        if re.fullmatch(r"[0-9]{5}-[0-9]{4}", value):
            value = value.split("-", 1)[0]
        if re.fullmatch(r"[0-9]{4}", value):
            value = "0" + value
        return value if re.fullmatch(r"[0-9]{5}", value) else ""

    def normalize_name(value):
        value = value.strip()
        return value.title() if value.isupper() or value.islower() else value

    def parse_updated(value):
        for fmt in ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S"):
            try:
                return datetime.strptime(value, fmt)
            except ValueError:
                pass
        raise ValueError(f"Invalid updated value: {value!r}")

    records = []
    for index, row in enumerate(rows):
        email = normalize_email(row["email"])
        phone = normalize_phone(row["phone"])
        if not email and not phone:
            continue

        records.append({
            "first_name": normalize_name(row["first_name"]),
            "last_name": normalize_name(row["last_name"]),
            "email": email,
            "phone": phone,
            "zip": normalize_zip(row["zip"]),
            "source": row["source"].strip().lower(),
            "tags": {
                tag.strip().lower()
                for tag in re.split(r"[;,]", row["tags"])
                if tag.strip()
            },
            "opted_out": row["opted_out"].strip().lower()
                         in {"y", "yes", "true", "1"},
            "_updated": parse_updated(row["updated"]),
            "_index": index,
        })

    # Union-find captures transitive matches without discarding bridge rows.
    parent = list(range(len(records)))
    size = [1] * len(records)

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    def union(a, b):
        a, b = find(a), find(b)
        if a == b:
            return
        if size[a] < size[b]:
            a, b = b, a
        parent[b] = a
        size[a] += size[b]

    by_email = {}
    by_phone_name = {}

    for i, row in enumerate(records):
        if row["email"]:
            previous = by_email.setdefault(row["email"], i)
            union(i, previous)

        if row["phone"] and row["last_name"]:
            key = (row["phone"], row["last_name"].casefold())
            previous = by_phone_name.setdefault(key, i)
            union(i, previous)

    groups = {}
    for i, row in enumerate(records):
        groups.setdefault(find(i), []).append(row)

    ordered_groups = sorted(
        groups.values(),
        key=lambda group: min(row["_index"] for row in group),
    )

    result = []
    fields = ("first_name", "last_name", "zip", "email", "phone", "source")

    for group in ordered_groups:
        preferred = sorted(
            group,
            key=lambda row: (
                row["source"] == "manual",
                row["_updated"],
                -row["_index"],
            ),
            reverse=True,
        )

        person = {
            field: next((row[field] for row in preferred if row[field]), "")
            for field in fields
        }
        person["tags"] = ";".join(sorted(
            {tag for row in group for tag in row["tags"]}
        ))
        person["opted_out"] = "Y" if any(row["opted_out"] for row in group) else "N"
        person["updated"] = max(
            row["_updated"] for row in group
        ).strftime("%Y-%m-%d")
        result.append(person)

    return result
